export const sharedSkillRuleTrust: unknown = [{"skillId":"ath-case-design","version":"0.1.1","ruleVersion":"0.1.1","releaseDigest":"b7088a02d5be42cd730bcf77ba0edf5f34d8a245f125ba2156804d27cff80238","sourceArchives":[{"kind":"zip","fileName":"ath-case-design-0.1.1.zip","sha256":"2cd902e0c34082e8d39b4ecabe0ee8b3cea8365d6f149ba900e49c890871cc83","bytes":14555},{"kind":"tgz","fileName":"aitesthub-case-design-skill-0.1.1.tgz","sha256":"c29bba020caf52fa60fba999696fdaa7eddb0f4073f73adf11ee02a9786befa9","bytes":67405}],"manifestSha256":"d0b218ce04f7bc75be8b9928f905182ee604769e6acacee222cc24aeeaf1bbca"},{"skillId":"ath-project-knowledge","version":"0.1.0","ruleVersion":"0.1.0","releaseDigest":"05fc96863eacaa1db324c920a0de5fa5cf0e701e6ffd48e4e3f0458b5993b0a7","sourceArchives":[{"kind":"zip","fileName":"ath-project-knowledge-0.1.0.zip","sha256":"f105bb3446bb10ff31aba70548c54183e5a30aa75512f52ac8e0ab7b16684bdb","bytes":899400}],"manifestSha256":"b0644f8d3978b11f3ef2e8791e8a49714961ce54691cf94be39ef32dc08db0a6"}];
